class CapturingCondition(object):
    """

    """
    allowed_capturing_conditions = [
        {'type': 'on change', 'regexp_str': r'on\s+change', 'attr_names': []},
        {'type': 'modulo', 'regexp_str': r'mod\s+(\d+)', 'attr_names': ['mod_index']}
    ]

    def __init__(self, name, params_list):
        assert name in [x['type'] for x in CapturingCondition.allowed_capturing_conditions],\
            'Not supported condition type'
        self.type = name
        self.attr_names = [x['attr_names'] for x in CapturingCondition.allowed_capturing_conditions
                           if x['type'] == self.type][0]
        self.attributes = {}
        assert len(params_list) == len(self.attr_names)
        for index, value in enumerate(params_list):
            self.attributes[self.attr_names[index]] = value

    @property
    def condition_type(self):
        """

        :return:
        """
        return self.type

    @property
    def available_attributes(self):
        """

        :return:
        """
        return self.attr_names

    @staticmethod
    def get_list_of_possible_conditions_regexp_strings():
        """

        :return:
        """
        return [x['regexp_str'] for x in CapturingCondition.allowed_capturing_conditions]
